(()=>{"use strict";const t=document.getElementById("loginDialog"),s=t?.querySelector(".login-card"),n=document.getElementById("loginPassword"),a=document.getElementById("loginPasswordToggle");if(!t||!s||!n||!a)return;t.addEventListener("cancel",e=>e.preventDefault()),a.addEventListener("click",()=>{const e=n.type==="text";n.type=e?"password":"text",a.setAttribute("aria-pressed",String(!e)),a.setAttribute("aria-label",e?"Mostrar senha":"Ocultar senha"),n.focus()});const l=()=>{const e=getComputedStyle(s),o=Math.max(0,s.clientWidth-parseFloat(e.paddingLeft)-parseFloat(e.paddingRight)),r=Math.min(1,Math.max(.72,o/300));t.style.setProperty("--login-turnstile-scale",String(r))};new ResizeObserver(l).observe(s),l()})();
